/** A place read in the head's own frame, and one in the robe's, on the page. */
const onPage = (x: number, y: number): P2 => { const q = HEAD.level(x, y); return [FACE.x + FACE.scale * q[0], FACE.y + FACE.scale * q[1]]; };
